function extrae_datos($file){
    echo "extrae_datos(file:->".$file."<-)\n";
        
    
    $return=[];
    $file= str_replace(".jpg", "", $file);
    $file= str_replace(".avi", "", $file);
    
    $aux= explode("_", $file);
    $return["camara_id"]=$aux[0];
    $return["fecha"]=$aux[1];
    
    
    $aux2= explode(".", $aux[2]);
    $return["hora"]=$aux2[0];
    
    $aux2= explode(".", $aux[3]);
    $return["segundos"]=$aux2[0];
    
    $return["fecha_completa"]=$return["fecha"]." ".$return["hora"];
            
    $aux3=date($return["fecha_completa"]);
    $fecha_foto=strtotime('+'.$return["segundos"].' second', strtotime($aux3));
    $return["fecha_completa_consegs"]=date('Y-m-d H:i:s',$fecha_foto);

    
    return $return;
                
}


function control_aforo($camara_id,$local_id){
    $sql=new Conectar();
    $tmp=new Conectar();    
    
    $sql->Consultar("camaras", "*","id=".$camara_id);
    if($sql->row["puerta"]==1 or $sql->row["salida"]==1){
        $tmp->Consultar("locales", "*", "id=".$local_id);
        $aforo_actual=$tmp->row["aforo_actual"];
        if($sql->row["puerta"]==1){
            $aforo_actual++;
        }
        if($sql->row["salida"]==1){
            $aforo_actual--;
        }
        $tmp->Actualizar("locales", ["aforo_actual"], [$aforo_actual], "id=".$local_id);
    }
    
    $sql->Desconectar();
    $tmp->Desconectar();
    
}

